import sys,json,csv
import numpy as np
from common import OUT,BASE,CACHE,SEEDS,dump,sha
GROUPS=('center','known_same_noncenter','known_C5','other_known_different','unknown');CFS=('drop_known_different_keep_unknown','only_known_same_C6')
def finite(x):
 x=np.asarray(x,float).reshape(-1);x=x[np.isfinite(x)];return {'n':len(x),'mean':float(x.mean()) if len(x) else None,'std':float(x.std()) if len(x) else None,'median':float(np.median(x)) if len(x) else None}
def ratio(a,b):return float(a/b) if b else None
def csvwrite(name,rows):
 with (OUT/name).open('x',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)

def main():
 assert json.loads((OUT/'extraction_status.json').read_text())['state']=='all3seeds_extracted';rows=[];contributionrows=[];cfrows=[];summaries={};provenance={};scalar_names=['known_noncenter_weight_mass','uniform_known_C5_fraction','actual_known_C5_fraction','C5_selection_excess_over_uniform','uniform_known_same_fraction','actual_known_same_fraction','same_selection_excess_over_uniform','known_same_V_C5_preferred_over_C6_fraction','known_same_V_nearest_C5_fraction','RF_interior_known_same_V_C5_preferred_over_C6_fraction','RF_interior_known_same_V_nearest_C5_fraction','center_V_C6_minus_C5_margin','sameclass_weight_before_CF','weight_on_CNN_RF_incomplete_rim']
 for seed in SEEDS:
  folder=OUT/f'seed_{seed}';manifest=json.loads((folder/'extraction_manifest.json').read_text());assert sha(manifest['checkpoint'])==manifest['checkpoint_sha256'];provenance[str(seed)]=manifest;fixed=np.load(folder/'fixed_subgroups.npz');fp=fixed['native_final_prediction'];safe=fixed['safe_nonreflected'];bd=fixed['boundary3x3'];interior=fixed['fully_labeled_same3x3'];gt=np.load(folder/'GT_patch_labels_offline.npy');native=np.load(folder/'native_T_source_scores.npy');cf=np.load(folder/'counterfactual_T_source_scores.npy');basepred=native.argmax(1);basemargin=native[:,5]-native[:,4];mass=np.load(folder/'GT_group_weight_mass.npy');neg=np.load(folder/'GT_group_negative_direction_magnitude.npy');signed=np.load(folder/'GT_group_normalized_direction_contribution.npy');shares=np.load(folder/'GT_group_negative_budget_fraction.npy');vbad=np.load(folder/'GT_group_V_C5_preferred_over_C6_weight_fraction.npy');vc5=np.load(folder/'GT_group_V_nearest_C5_weight_fraction.npy');center=np.load(folder/'center_V_source_scores.npy');positionnegative=np.load(folder/'position_negative_token_direction_magnitude.npy',mmap_mode='r');allscalars={name:np.load(folder/(name+'.npy')) for name in scalar_names};normvalid_rf=np.zeros((13,13),bool);normvalid_rf[2:11,2:11]=True;rim=~normvalid_rf.flatten()
  masks={'all_C6_nonreflected':safe,'C6_final_C5_nonreflected':safe&(fp==4),'C6_correct_nonreflected':safe&(fp==5),'C6_other_error_nonreflected':safe&(fp!=4)&(fp!=5),'C6_final_C5_boundary_nonreflected':safe&(fp==4)&bd,'C6_correct_boundary_nonreflected':safe&(fp==5)&bd,'C6_final_C5_fully_same3x3_nonreflected':safe&(fp==4)&interior,'C6_correct_fully_same3x3_nonreflected':safe&(fp==5)&interior,'C6_final_C5_native_all':fp==4,'C6_correct_native_all':fp==5};summaries[str(seed)]={}
  for subset,m in masks.items():
   n=int(m.sum());rec={'n':n}
   if not n:summaries[str(seed)][subset]=rec;continue
   rec.update({name:finite(v[m]) for name,v in allscalars.items()});rec['native_T_nearest_source_C5_fraction']=float((basepred[m]==4).mean());rec['native_T_nearest_source_C6_fraction']=float((basepred[m]==5).mean());rec['center_V_nearest_source_C5_fraction']=float((center[m].argmax(1)==4).mean());rec['center_V_nearest_source_C6_fraction']=float((center[m].argmax(1)==5).mean());rec['center_V_C5_preferred_over_C6_fraction']=float((center[m,4]>center[m,5]).mean());rec['native_T_C6_minus_C5_margin']=finite(basemargin[m]);rec['GT_known_neighbor_coverage_noncenter']=finite(((gt[m]>=0).sum(1)-1)/168);rec['negative_token_contribution_on_RF_rim_fraction_pooled']=ratio(positionnegative[m][:,rim].sum(),positionnegative[m].sum());rec['GT_groups']={};rec['counterfactuals']={}
   row={'seed':seed,'subset':subset,'n':n,'T_nearest_source_C5_percent':100*rec['native_T_nearest_source_C5_fraction'],'T_nearest_source_C6_percent':100*rec['native_T_nearest_source_C6_fraction'],'center_V_nearest_source_C5_percent':100*rec['center_V_nearest_source_C5_fraction'],'center_V_C5_preferred_over_C6_percent':100*rec['center_V_C5_preferred_over_C6_fraction']}
   for name in scalar_names:row[name+'_mean']=rec[name]['mean']
   rows.append(row)
   for j,label in enumerate(GROUPS):
    g={'W_mass':finite(mass[m,j]),'normalized_signed_direction_contribution':finite(signed[m,j]),'negative_budget_fraction_per_patch':finite(shares[m,j]),'negative_budget_fraction_pooled_absolute':ratio(neg[m,j].sum(),neg[m].sum()),'V_C5_preferred_over_C6_weight_fraction':finite(vbad[m,j]),'V_nearest_C5_weight_fraction':finite(vc5[m,j])};rec['GT_groups'][label]=g
    contributionrows.append({'seed':seed,'subset':subset,'group':label,'n':n,'W_mass_mean':g['W_mass']['mean'],'normalized_signed_contribution_mean':g['normalized_signed_direction_contribution']['mean'],'negative_budget_mean_patch_fraction':g['negative_budget_fraction_per_patch']['mean'],'negative_budget_pooled_fraction':g['negative_budget_fraction_pooled_absolute'],'V_C5_preferred_weight_fraction_mean':g['V_C5_preferred_over_C6_weight_fraction']['mean'],'V_nearest_C5_weight_fraction_mean':g['V_nearest_C5_weight_fraction']['mean']})
   for j,label in enumerate(CFS):
    scores=cf[:,j];pred=scores.argmax(1);margin=scores[:,5]-scores[:,4];old5=m&(basepred==4);old_pair=m&(basemargin<0);old6=m&(basepred==5)
    d={'T_nearest_source_C5_fraction':float((pred[m]==4).mean()),'T_nearest_source_C6_fraction':float((pred[m]==5).mean()),'C6_minus_C5_margin':finite(margin[m]),'delta_C6_minus_C5_margin':finite(margin[m]-basemargin[m]),'original_T_C5_count':int(old5.sum()),'original_T_C5_to_CF_C6_count':int((old5&(pred==5)).sum()),'original_T_C5_to_CF_C6_recovery_fraction':ratio((old5&(pred==5)).sum(),old5.sum()),'original_T_C6_to_CF_other_count':int((old6&(pred!=5)).sum()),'negative_pair_to_positive_pair_fraction':ratio((old_pair&(margin>0)).sum(),old_pair.sum())};rec['counterfactuals'][label]=d
    cfrows.append({'seed':seed,'subset':subset,'counterfactual':label,'n':n,'orig_T_nearest_C5_percent':100*rec['native_T_nearest_source_C5_fraction'],'orig_T_nearest_C6_percent':100*rec['native_T_nearest_source_C6_fraction'],'CF_T_nearest_C5_percent':100*d['T_nearest_source_C5_fraction'],'CF_T_nearest_C6_percent':100*d['T_nearest_source_C6_fraction'],'orig_T_C5_count':d['original_T_C5_count'],'orig_T_C5_to_CF_C6_count':d['original_T_C5_to_CF_C6_count'],'orig_T_C5_to_CF_C6_recovery_fraction':d['original_T_C5_to_CF_C6_recovery_fraction'],'delta_C6_minus_C5_margin_mean':d['delta_C6_minus_C5_margin']['mean'],'pair_negative_to_positive_fraction':d['negative_pair_to_positive_pair_fraction']})
   summaries[str(seed)][subset]=rec
  dump(folder/'summary.json',summaries[str(seed)])
 csvwrite('selection_and_value_by_subgroup.csv',rows);csvwrite('signed_position_contributions_by_GT_group.csv',contributionrows);csvwrite('GT_counterfactual_token_geometry.csv',cfrows)
 result={'seeds':SEEDS,'epoch':200,'per_seed':summaries,'extraction_provenance':provenance,'primary_scope':'nonreflected patches; each seed own source-train prototypes; final C6->C5 vs C6correct comparison','no_training_or_new_modules':True,'target_GT_only_offline':True,'limitations':['GT unknown is not assumed different or same; both unknown-preserving and strict-known-same counterfactuals reported.','Source V center prototypes diagnose geometric resemblance, not true semantic labels of CNN features; neighbor V at patch rim has incomplete CNN context, interior sensitivity reported.','CF tokens are off-training-distribution oracle diagnostic; no Transformer/logit OA gain claimed.','Signed W*V contribution does not uniquely identify a causal mechanism; oracleW rescue tests whether selection correction alone can help fixed V.','W and V were jointly trained; negative value direction at GTsame positions can come from spectral/domain mismatch or receptive-field context mixing.','Patch overlap and same target pixels across seeds are not independent observations.','No automatic architecture redesign/experiment follows this diagnosis.']}
 dump(OUT/'summary.json',result);dump(OUT/'provenance.json',{'code_sha256':{p.name:sha(p) for p in OUT.glob('*.py')},'protocol_sha256':sha(OUT/'PROTOCOL.txt'),'checkpoints':provenance,'reference_class_geometry_summary_sha256':sha(GEOM/'summary.json') if False else sha(BASE.parent/'tokenizer_class_correspondence_houston_v1/summary.json'),'frozen_source_input_manifest_sha256':sha(CACHE/'fixed_inputs.json'),'Pavia_modified':False})
 for seed in SEEDS:
  r=summaries[str(seed)]['C6_final_C5_nonreflected'];print(seed,json.dumps(r),flush=True)
if __name__=='__main__':main()
